mapper.select:
select pecd.pecd_Id as pecdId, pecd.pec_Id as pecId, c.C_Name as peCompanyName, c.C_Name_History as peCompanyNameHistory, d.D_Name as peUnitName, pc.C_Name as pBuildUnitName, c.C_Abbreviation as peCompanyAbbName, pc.C_Abbreviation as pConsAbbName, prod.D_Name as pCompDepName, case when p.Pe_Contract_Category='02' then sr.Sc_Name else con.con_Name end as conName, case when p.Pe_Contract_Category='02' then sr.Sc_Money else con.con_Money_Total end as conMoneyTotal, case when p.Pe_Contract_Category='02' then sr.Sc_Type else con.con_Type end as conType, case when p.Pe_Contract_Category='02' then sr.Sc_Code else con.con_Code end as conCode, con.Con_Execution as conExecution, pro.P_Name as pName, pro.P_Name_History as pNameHistory,
from Pe_Info_Collect_Dtl pecd left join Pe_Info_Collect pec on pec.pec_Id=pecd.pec_Id left join Pe_Info p on pecd.pe_id=p.Pe_id left join Con_Contract con on p.Pe_Con_Id=con.Con_Id left join Pre_Project pro on pro.P_Id=p.Pe_Project_Id left join SYS_Company c on c.C_Id=p.Pe_Company_Id left join SYS_Department d on d.D_Id=p.Pe_Unit_Id left join SYS_Company pc on pc.C_Id=pro.P_Construction_Unit left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department left join Subcontract_Record sr on p.Pe_Sub_Contract=sr.Sc_Id
and p.Te_Id = #{params.teId}
and p.Pe_Project_Id = #{params.pId}
and pecd.pec_Id = #{params.pecId}
and pecd.pec_Id is null
and p.Pe_Year = #{params.peYear}
and p.Pe_Quarter = #{params.peQuarter}
and p.Pe_Type = #{params.peType}
and pro.P_Construction_Unit = #{params.pConstructionUnit}
and p.Pe_Unit_Id = #{params.peUnitId}
and pec.Pec_Flow_State = 7
and p.Pe_State = #{params.peState}
and p.Pe_Company_Id = #{params.peCompanyId}
and con.con_Type = #{params.conType}
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and con.con_Name like concat('%',#{params.conName},'%')
and likeCname(#{params.peCompanyName},c.C_Id)=true
and c.C_Name like concat('%',#{params.peCompanyName},'%')
order by p.${params.sortFiled} ${params.sortType}
order by p.Pe_Create_Time desc

select c.C_Name as peCompanyName, c.C_Name_History as peCompanyNameHistory, d.D_Name as peUnitName, pc.C_Name as pBuildUnitName, c.C_Abbreviation as peCompanyAbbName, pc.C_Abbreviation as pConsAbbName, prod.D_Name as pCompDepName, case when p.Pe_Contract_Category='02' then sr.Sc_Name else con.con_Name end as conName, case when p.Pe_Contract_Category='02' then sr.Sc_Money else con.con_Money_Total end as conMoneyTotal, case when p.Pe_Contract_Category='02' then sr.Sc_Type else con.con_Type end as conType, case when p.Pe_Contract_Category='02' then sr.Sc_Code else con.con_Code end as conCode, con.Con_Execution as conExecution, pro.P_Name_History as pNameHistory, pro.P_Name as pName,
from Pe_Info p left join Con_Contract con on p.Pe_Con_Id=con.Con_Id left join Pre_Project pro on pro.P_Id=p.Pe_Project_Id left join SYS_Company c on c.C_Id=p.Pe_Company_Id left join SYS_Department d on d.D_Id=p.Pe_Unit_Id left join SYS_Company pc on pc.C_Id=pro.P_Construction_Unit left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department left join Subcontract_Record sr on p.Pe_Sub_Contract=sr.Sc_Id where p.Pe_Flow_State=7 and p.pe_Id not in ( select d.pe_id from Pe_Info_Collect_Dtl d left join Pe_Info_Collect pic on pic.Pec_Id=d.Pec_Id where pic.Pec_Flow_State!=3 and d.pe_id is not null )
and p.Te_Id = #{params.teId}
and p.Pe_Year = #{params.peYear}
and p.Pe_Quarter = #{params.peQuarter}
and p.Pe_Type = #{params.peType}
and pro.P_Construction_Unit = #{params.pConstructionUnit}
and p.Pe_Unit_Id = #{params.peUnitId}
and con.Con_Party_A_Id = #{params.conPartyAId}
and p.Pe_Competent_Department = #{params.pecDepartment}
order by p.${params.sortFiled} ${params.sortType}
order by p.Pe_Create_Time desc
limit #{params.start},#{params.size}

select
count(1)
from Pe_Info p
left join Pre_Project pro on pro.P_Id=p.Pe_Project_Id
left join Con_Contract con on p.Pe_Con_Id=con.Con_Id
where p.Pe_Flow_State=7 and
p.pe_Id not in (
select d.pe_id from Pe_Info_Collect_Dtl d
left join Pe_Info_Collect pic on pic.Pec_Id=d.Pec_Id
where pic.Pec_Flow_State!=3 and d.pe_id is not null
)

    and p.Te_Id = #{params.teId}


    and p.Pe_Year = #{params.peYear}


    and p.Pe_Quarter = #{params.peQuarter}


    and p.Pe_Type = #{params.peType}


    and pro.P_Construction_Unit = #{params.pConstructionUnit}


    and p.Pe_Unit_Id = #{params.peUnitId}


    and con.Con_Party_A_Id = #{params.conPartyAId}


    and p.Pe_Competent_Department = #{params.pecDepartment}
